import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_none_is_included_in_flag_rate_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None)]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_counts_transcripts_not_groups():
    groups = {"a": [event("x", 1, True)], "b": [event("y", 1, None)] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("days, expected", [(0, 0), (2, 5), (9, 6)])
def test_trailing_window(days, expected):
    assert flags_in_window([1, 2, 3], days) == expected


def test_log_skips_comments_and_blank_lines_and_strips_fields():
    lines = ["", " \t", "  # comment", " x , 2 , 1 ", "y,3,0", "z,4, "]
    assert parse_transcript_log(lines) == [
        event("x", 2, True), event("y", 3, False), event("z", 4, None),
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,,", "x,no,1"])
def test_log_error_includes_original_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["", "  # comment", "x,2,1", bad])


def test_duplicate_ids_keep_last_input_record_then_sort():
    old, new = event("x", 7, True), event("x", 3, None)
    a, z = event("a", 3, False), event("z", 1, True)
    assert dedupe_transcripts([old, z, new, a]) == [z, a, new]


def test_daily_counts_include_only_requested_days():
    events = [event(str(i), day, True) for i, day in enumerate([1, 2, 2, 4, 7])]
    events += [event("x", 3, False), event("y", 3, None)]
    assert daily_flag_counts(events, 2, 5) == [2, 0, 1, 0]
    assert daily_flag_counts(events, 5, 2) == []


def test_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [event("x", 1, True)], "b": [event("y", 4, True), event("z", 4, False)], "c": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"c": []}, 1) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_rankings_and_rates():
    groups = {"z": [event("z", 1, True)], "empty": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 9) == ["a", "z", "b"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0),
    ]


@pytest.mark.parametrize("counts, expected", [([], 0), ([-1, 0], 0), ([1, 0, 2, 3, -1, 4], 2)])
def test_streak_counts_only_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
